import numpy as np

def equilibrium_type(f, y_star, h=1e-4):
    """'stable', 'unstable' or 'semi-stable', from the sign of f on each side."""
    left, right = f(y_star - h), f(y_star + h)
    if left > 0 and right < 0:
        return "stable"
    if left < 0 and right > 0:
        return "unstable"
    return "semi-stable"

def equilibria(coeffs):
    """Sorted real roots of the polynomial f (highest power first), to 6 places."""
    roots = np.roots(coeffs)
    real = [float(round(r.real, 6)) for r in roots if abs(r.imag) < 1e-9]
    return sorted(real)
